import json
import collections

# Retrieve parameters from 'input_data'
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
start_z = int(input_data.get('start_z', 0))
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])
target_z = int(input_data.get('target_z', 0))

def find_path():
    # Model state as (x, y, z)
    # z=0 is ground level, z=1 is plateau level.

    # Check bounds
    if not (0 <= start_x < 30 and 0 <= start_y < 30):
        return None
    if not (0 <= target_x < 30 and 0 <= target_y < 30):
        return None

    # Define Map 0_219 (West) Obstacles
    if map_id == "0_219":
        # Ground Level z=0:
        # Rest House 3 (11,11) to (14,13)
        rh3 = set()
        for x in range(11, 15):
            for y in range(11, 14):
                rh3.add((x, y))

        # Water/Lake:
        # Column 9 Rows 10-13, Columns 1-8 Row 13, Columns 3-8 Rows 13-15
        water = set()
        for y in range(10, 14):
            water.add((9, y))
        for x in range(1, 9):
            water.add((x, 13))

        # Ground Tree Walls / Fences:
        # Row 19 Columns 8-17, Column 18 Rows 20-23, Column 24 Rows 1-12
        tree_walls = set()
        for x in range(8, 18):
            tree_walls.add((x, 19))
        for y in range(20, 24):
            tree_walls.add((18, y))
        for y in range(1, 13):
            tree_walls.add((24, y))

        # Explicit ground-level cliff wall blocks from critique:
        # 1. Column 23 (Rows 14-17) is a solid cliff wall at ground level.
        # 2. Column 17 (Rows 6-13) is a solid cliff wall at ground level.
        cliff_walls = set()
        for y in range(14, 18):
            cliff_walls.add((23, y))
        for y in range(6, 14):
            cliff_walls.add((17, y))

        # Stairs:
        # Western Stairs: (6, 19)
        # Eastern Stairs: (21, 17)
        stairs = {(6, 19), (21, 17)}

        # Plateau Level z=1:
        # Central/Western Plateau is Columns 11-16, Rows 6-16
        # Eastern connection is Columns 17-22, Rows 14-16
        # Stairs: (6, 18), (6, 19), (21, 16), (21, 17)
        plateau_tiles = set()
        for x in range(11, 17):
            for y in range(6, 17):
                plateau_tiles.add((x, y))
        for x in range(17, 23):
            for y in range(14, 17):
                plateau_tiles.add((x, y))
        plateau_tiles.add((6, 18))
        plateau_tiles.add((6, 19))
        plateau_tiles.add((21, 16))
        plateau_tiles.add((21, 17))

        def is_valid_move(cx, cy, cz, nx, ny):
            # Check map boundary
            if not (0 <= nx < 30 and 0 <= ny < 30):
                return False, cz

            # Stairs elevation logic:
            nz = cz
            if cz == 0:
                # Can only step onto stairs from ground
                if (nx, ny) in stairs:
                    nz = 1
                else:
                    # Cannot step onto plateau from ground without stairs
                    if (nx, ny) in plateau_tiles:
                        return False, cz
                    # Check other ground obstacles
                    if (nx, ny) in rh3 or (nx, ny) in water or (nx, ny) in tree_walls or (nx, ny) in cliff_walls:
                        return False, cz
            else: # cz == 1 (on plateau)
                # If we are on stairs, stepping off the plateau to a ground tile transitions nz to 0
                if (cx, cy) in stairs and (nx, ny) not in plateau_tiles:
                    nz = 0
                else:
                    # Must stay on plateau tiles if we didn't descend stairs
                    if (nx, ny) not in plateau_tiles:
                        return False, cz

            return True, nz

    else:
        # Standard fallback for other maps
        def is_valid_move(cx, cy, cz, nx, ny):
            return (0 <= nx < 40 and 0 <= ny < 40), cz

    # BFS search: queue holds (x, y, z, path)
    queue = collections.deque([(start_x, start_y, start_z, [])])
    visited = {(start_x, start_y, start_z)}

    while queue:
        cx, cy, cz, path = queue.popleft()
        if (cx, cy, cz) == (target_x, target_y, target_z):
            return path

        for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy
            valid, nz = is_valid_move(cx, cy, cz, nx, ny)
            if valid and (nx, ny, nz) not in visited:
                visited.add((nx, ny, nz))
                queue.append((nx, ny, nz, path + [move]))

    return None

path = find_path()
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
